// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	page, _ := s.InvoicePage(orgID, f, nil, math.MaxInt)
	return page
}

// InvoicePosition is where a page of invoices starts: after the invoice created at CreatedAt with this ID.
type InvoicePosition struct {
	CreatedAt time.Time
	ID        string
}

// InvoicePage returns up to limit of an organization's invoices that match f, oldest first (ties by ID), starting after
// the position, or from the first invoice when after is nil. more reports whether a matching invoice follows the page.
func (s *Store) InvoicePage(orgID string, f InvoiceFilter, after *InvoicePosition, limit int) (page []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoiceIDs[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool { return after.before(s.invoices[ids[i]]) })
	}
	page = []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		if len(page) == limit {
			return page, true
		}
		page = append(page, copyInvoice(inv))
	}
	return page, false
}

// before reports whether the position comes before the invoice in listing order.
func (p InvoicePosition) before(inv Invoice) bool {
	if !p.CreatedAt.Equal(inv.CreatedAt) {
		return p.CreatedAt.Before(inv.CreatedAt)
	}
	return p.ID < inv.ID
}

// invoiceBefore reports whether a comes before b in listing order: oldest first, ties by ID.
func invoiceBefore(a, b Invoice) bool {
	return InvoicePosition{CreatedAt: a.CreatedAt, ID: a.ID}.before(b)
}

// indexInvoice adds an invoice to its organization's listing order. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceIDs[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return invoiceBefore(inv, s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoiceIDs[inv.OrgID] = ids
}

