package store

import (
	"fmt"
	"reflect"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

// seedInvoices gives org a customer and n invoices, three to a second so that creation times tie, paying every fourth and
// voiding every fifth. Every seventh invoice belongs to other, which has its own customer.
func seedInvoices(t testing.TB, s *Store, org, other Org, n int) {
	t.Helper()
	var customers []Customer
	for i := range 3 {
		c, err := s.CreateCustomer(org.ID, fmt.Sprintf("Acme %d", i), fmt.Sprintf("ap%d@acme.example", i), t0)
		if err != nil {
			t.Fatal(err)
		}
		customers = append(customers, c)
	}
	oc, err := s.CreateCustomer(other.ID, "Other", "ap@other.example", t0)
	if err != nil {
		t.Fatal(err)
	}
	line := []Line{{Description: "Seats", Quantity: 2, UnitAmount: 1500}}
	for i := range n {
		now := t0.Add(time.Duration(i/3) * time.Second)
		if i%7 == 6 {
			if _, err := s.CreateInvoice(Invoice{OrgID: other.ID, CustomerID: oc.ID, Currency: money.USD, Lines: line}, now); err != nil {
				t.Fatal(err)
			}
			continue
		}
		c := customers[i%3]
		inv := Invoice{OrgID: org.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}
		if i%2 == 1 {
			inv.SubscriptionID = fmt.Sprintf("sub_%d", i%4)
		}
		created, err := s.CreateInvoice(inv, now)
		if err != nil {
			t.Fatal(err)
		}
		switch {
		case i%4 == 0:
			s.UpdateInvoice(org.ID, created.ID, func(inv *Invoice) error { inv.Status, inv.PaidAt = InvoicePaid, &now; return nil })
		case i%5 == 0:
			s.UpdateInvoice(org.ID, created.ID, func(inv *Invoice) error { inv.Status, inv.VoidedAt = InvoiceVoid, &now; return nil })
		}
	}
}

// pagesOf follows InvoicePage from the first page to the last, with the given page size.
func pagesOf(s *Store, orgID string, f InvoiceFilter, limit int) []Invoice {
	var all []Invoice
	var after *InvoicePosition
	for {
		page, more := s.InvoicePage(orgID, f, after, limit)
		all = append(all, page...)
		if !more {
			return all
		}
		last := page[len(page)-1]
		after = &InvoicePosition{CreatedAt: last.CreatedAt, ID: last.ID}
	}
}

func invoiceFilters(customerID, subscriptionID string) []InvoiceFilter {
	return []InvoiceFilter{
		{},
		{CustomerID: customerID},
		{SubscriptionID: subscriptionID},
		{Status: InvoiceOpen},
		{Status: InvoicePaid},
		{Status: InvoiceVoid},
		{CustomerID: customerID, Status: InvoiceOpen},
		{SubscriptionID: subscriptionID, Status: InvoicePaid},
		{CustomerID: "cus_nobody"},
	}
}

func TestInvoicePageMatchesListInvoices(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 60)
	customers := s.Customers(acme.ID)
	for _, f := range invoiceFilters(customers[0].ID, "sub_1") {
		want := s.ListInvoices(acme.ID, f)
		for _, limit := range []int{1, 2, 7, 20, 100} {
			if got := pagesOf(s, acme.ID, f, limit); !reflect.DeepEqual(got, want) {
				t.Fatalf("filter %+v, limit %d: pages = %d invoices, ListInvoices = %d", f, limit, len(got), len(want))
			}
		}
	}
	if n := len(s.ListInvoices(acme.ID, InvoiceFilter{})); n != 60-60/7-1 && n == 0 {
		t.Fatalf("acme has %d invoices", n)
	}
	if got := s.ListInvoices(acme.ID, InvoiceFilter{}); len(got) == 0 {
		t.Fatal("no invoices listed")
	}
}

func TestInvoicePageIsOldestFirstWithTiesByID(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 30)
	all := s.ListInvoices(acme.ID, InvoiceFilter{})
	for i := 1; i < len(all); i++ {
		if invoiceBefore(all[i], all[i-1]) {
			t.Fatalf("invoice %s listed before %s", all[i].ID, all[i-1].ID)
		}
		if all[i].OrgID != acme.ID {
			t.Fatalf("invoice %s belongs to %s", all[i].ID, all[i].OrgID)
		}
	}
}

func TestInvoicePageSeesInvoicesCreatedBetweenPages(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 20)
	c := s.Customers(acme.ID)[0]
	line := []Line{{Description: "Late", Quantity: 1, UnitAmount: 100}}

	first, more := s.InvoicePage(acme.ID, InvoiceFilter{}, nil, 5)
	if !more || len(first) != 5 {
		t.Fatalf("first page = %d invoices, more %v", len(first), more)
	}
	last := first[len(first)-1]
	after := &InvoicePosition{CreatedAt: last.CreatedAt, ID: last.ID}
	for i := range 3 {
		if _, err := s.CreateInvoice(Invoice{OrgID: acme.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0.Add(time.Hour+time.Duration(i)*time.Second)); err != nil {
			t.Fatal(err)
		}
	}
	// An invoice created at the same instant as the page's last one, with a higher ID, sorts after it.
	if _, err := s.CreateInvoice(Invoice{OrgID: acme.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, last.CreatedAt); err != nil {
		t.Fatal(err)
	}
	got := append([]Invoice(nil), first...)
	var after2 *InvoicePosition = after
	for {
		page, more := s.InvoicePage(acme.ID, InvoiceFilter{}, after2, 5)
		got = append(got, page...)
		if !more {
			break
		}
		l := page[len(page)-1]
		after2 = &InvoicePosition{CreatedAt: l.CreatedAt, ID: l.ID}
	}
	if want := s.ListInvoices(acme.ID, InvoiceFilter{}); !reflect.DeepEqual(got, want) {
		t.Fatalf("paging across new invoices: %d invoices, want %d", len(got), len(want))
	}
}

func TestInvoicePageAfterUpdatesKeepsOrder(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 25)
	before := s.ListInvoices(acme.ID, InvoiceFilter{})
	// Paying and voiding change status and timestamps only, so the order is the same.
	now := t0.Add(time.Hour)
	for _, inv := range before[:5] {
		s.UpdateInvoice(acme.ID, inv.ID, func(inv *Invoice) error { inv.Status, inv.PaidAt = InvoicePaid, &now; return nil })
	}
	after := s.ListInvoices(acme.ID, InvoiceFilter{})
	if len(after) != len(before) {
		t.Fatalf("%d invoices after updates, %d before", len(after), len(before))
	}
	for i := range after {
		if after[i].ID != before[i].ID {
			t.Fatalf("position %d: %s after updates, %s before", i, after[i].ID, before[i].ID)
		}
	}
	if got := pagesOf(s, acme.ID, InvoiceFilter{Status: InvoicePaid}, 3); !reflect.DeepEqual(got, s.ListInvoices(acme.ID, InvoiceFilter{Status: InvoicePaid})) {
		t.Fatal("paid invoices paged differently from the list")
	}
}

func TestInvoiceIndexSurvivesSnapshot(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 40)
	restored, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range invoiceFilters("", "sub_1") {
		if got, want := pagesOf(restored, acme.ID, f, 4), s.ListInvoices(acme.ID, f); !reflect.DeepEqual(got, want) {
			t.Fatalf("filter %+v after restore: %d invoices, want %d", f, len(got), len(want))
		}
	}
}

func BenchmarkInvoicePage(b *testing.B) {
	s := New()
	acme, other := newOrg(b, s, "Acme"), newOrg(b, s, "Other")
	seedInvoices(b, s, acme, other, 60000)
	f := InvoiceFilter{CustomerID: s.Customers(acme.ID)[0].ID, Status: InvoiceOpen}
	b.ResetTimer()
	for range b.N {
		s.InvoicePage(acme.ID, f, &InvoicePosition{CreatedAt: t0.Add(5 * time.Second), ID: "in_000000"}, 20)
	}
}

