func TestInvoicePageAfterUpdatesKeepsOrder(t *testing.T) {
	s := New()
	acme, other := newOrg(t, s, "Acme"), newOrg(t, s, "Other")
	seedInvoices(t, s, acme, other, 25)
	before := s.ListInvoices(acme.ID, InvoiceFilter{})
	// Paying and voiding change status and timestamps only, so the order is the same.
	now := t0.Add(time.Hour)
	for _, inv := range before[:5] {
		s.UpdateInvoice(acme.ID, inv.ID, func(inv *Invoice) error { inv.Status, inv.PaidAt = InvoicePaid, &now; return nil })
	}
	after := s.ListInvoices(acme.ID, InvoiceFilter{})
	if len(after) != len(before) {
		t.Fatalf("%d invoices after updates, %d before", len(after), len(before))
	}
	for i := range after {
		if after[i].ID != before[i].ID {
			t.Fatalf("position %d: %s after updates, %s before", i, after[i].ID, before[i].ID)
		}
	}
	if got := pagesOf(s, acme.ID, InvoiceFilter{Status: InvoicePaid}, 3); !reflect.DeepEqual(got, s.ListInvoices(acme.ID, InvoiceFilter{Status: InvoicePaid})) {
		t.Fatal("paid invoices paged differently from the list")
	}
}

