package api_test

import (
	"net/http"
	"net/url"
	"testing"

	"example.com/tally/internal/apitest"
)

// invoiceIDs answers the IDs of one page of GET /v1/invoices and the cursor of the next page.
func invoiceIDs(t *testing.T, e *apitest.Env, key, path string) ([]string, string) {
	t.Helper()
	var page struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
		NextCursor string `json:"next_cursor"`
	}
	e.MustDo(http.StatusOK, "GET", path, key, nil, &page)
	ids := []string{}
	for _, it := range page.Items {
		ids = append(ids, it.ID)
	}
	return ids, page.NextCursor
}

func TestInvoiceListPagingFollowsNewInvoices(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	g := e.CreateCustomer(e.Globex, "Gus", "gus@example.com")
	create := func(org apitest.Org, customer string) string {
		var inv struct {
			ID string `json:"id"`
		}
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": customer, "currency": "USD",
			"lines": []map[string]any{{"description": "Seats", "quantity": 1, "unit_amount": 1000}}}, &inv)
		return inv.ID
	}
	var want []string
	for range 5 {
		want = append(want, create(e.Acme, c.ID))
		create(e.Globex, g.ID)
	}

	ids, next := invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?limit=2")
	if len(ids) != 2 || next == "" {
		t.Fatalf("first page = %v, next_cursor %q", ids, next)
	}
	// Invoices created between pages come after the ones already listed.
	for range 2 {
		want = append(want, create(e.Acme, c.ID))
	}
	got := ids
	for next != "" {
		var more []string
		more, next = invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?limit=2&cursor="+url.QueryEscape(next))
		got = append(got, more...)
	}
	if len(got) != len(want) {
		t.Fatalf("paged %d invoices, want %d: %v", len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("position %d = %s, want %s", i, got[i], want[i])
		}
	}
	if all, next := invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?limit=100"); next != "" || len(all) != len(want) {
		t.Fatalf("one page = %d invoices, next_cursor %q", len(all), next)
	}
}

func TestInvoiceListFiltersAndErrors(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	d := e.CreateCustomer(e.Acme, "Dan", "dan@example.com")
	var voided, open []string
	for i := range 6 {
		customer := c.ID
		if i%3 == 2 {
			customer = d.ID
		}
		var inv struct {
			ID string `json:"id"`
		}
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": customer, "currency": "USD",
			"lines": []map[string]any{{"description": "Seats", "quantity": 1, "unit_amount": 1000}}}, &inv)
		if i == 1 || i == 4 {
			e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+inv.ID+"/void", e.Acme.Key, nil, nil)
			voided = append(voided, inv.ID)
		} else {
			open = append(open, inv.ID)
		}
	}

	if ids, _ := invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?status=void"); len(ids) != len(voided) || ids[0] != voided[0] || ids[1] != voided[1] {
		t.Fatalf("void invoices = %v, want %v", ids, voided)
	}
	if ids, _ := invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?customer_id="+d.ID); len(ids) != 2 {
		t.Fatalf("Dan's invoices = %v", ids)
	}
	if ids, _ := invoiceIDs(t, e, e.Acme.Key, "/v1/invoices?customer_id="+c.ID+"&status=open"); len(ids) != 2 || ids[0] != open[0] || ids[1] != open[2] {
		t.Fatalf("Jane's open invoices = %v, want %v", ids, []string{open[0], open[2]})
	}
	if ids, _ := invoiceIDs(t, e, e.Globex.Key, "/v1/invoices"); len(ids) != 0 {
		t.Fatalf("Globex sees Acme's invoices: %v", ids)
	}

	for path, code := range map[string]string{
		"/v1/invoices?status=lost":    "invalid_status",
		"/v1/invoices?limit=0":        "invalid_limit",
		"/v1/invoices?limit=101":      "invalid_limit",
		"/v1/invoices?cursor=%%%":     "invalid_cursor",
		"/v1/invoices?cursor=e30":     "invalid_cursor",
	} {
		if r := e.Do("GET", path, e.Acme.Key, nil); r.Code != http.StatusBadRequest || r.Map(t)["error"] != code {
			t.Errorf("GET %s = %s, want %s", path, r, code)
		}
	}
}

