func TestInvoiceListPagingFollowsNewInvoices(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	g := e.CreateCustomer(e.Globex, "Gus", "gus@example.com")
	create := func(org apitest.Org, customer string) string {
		var inv struct {
			ID string `json:"id"`
		}
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": customer, "currency": "USD",
